```

- Import PlanProgress from task-types.ts
- Add a getPlanProgress policy function that:
  1. Checks if plan.xml exists at taskPath (using deps.fs.exists and deps.fs.joinPath)
  2. If not, returns undefined (FR4)
  3. If yes, reads content with deps.fs.readFile
  4. Calls planParser.getPlanProgress(content) and returns the result
  5. Wraps in try/catch, returns undefined on error

```typescript
function getPlanProgress(taskPath: string): PlanProgress | undefined {
  const planPath = deps.fs.joinPath(taskPath, 'plan.xml');
  if (!deps.fs.exists(planPath)) return undefined;
  try {
    const content = deps.fs.readFile(planPath);
    return planParser.getPlanProgress(content);
  } catch {
    return undefined;
  }
}
```

